UPDATE t_card_bin_library_version
SET status = 'INVALID', failure_reason = #{failureReason}, total_rows = #{totalRows}, error_rows = #{errorRows},
    version = version + 1,
    update_time = #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}
WHERE version_id = #{versionId} AND status = 'VALIDATING' AND version = #{version}

UPDATE t_card_bin_library_version
SET processed_rows = #{processedRows}, version = version + 1,
    update_time = #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}
WHERE version_id = #{versionId} AND status = 'VALIDATING' AND version = #{version}

UPDATE t_card_bin_library_version
SET status = 'VALID', total_rows = #{totalRows}, processed_rows = #{totalRows}, version = version + 1,
    update_time = #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}
WHERE version_id = #{versionId} AND status = 'VALIDATING' AND version = #{version}

UPDATE t_card_bin_library_version
SET status = 'RETIRED', active_slot = NULL, version = version + 1,
    update_time = #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}
WHERE version_id = #{versionId} AND status = 'ACTIVE' AND active_slot = 1 AND version = #{version}

UPDATE t_card_bin_library_version
SET status = 'ACTIVE', active_slot = 1, version = version + 1,
    update_time = #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}
WHERE version_id = #{versionId} AND active_slot IS NULL AND version = #{version}
  AND status = #{expectedStatus,javaType=com.paytech.card.api.enums.BinLibraryVersionStatus,typeHandler=com.paytech.foundation.mybatis.typehandler.CodeEnumTypeHandler,jdbcType=VARCHAR}
